  ('official_bank_bua202', 'keep', 1, $official_bank_source${"itemId":"87e262d1-440c-5e57-883f-7332bfdd1a64","revise":true,"payload":{"prompt":"Structuring pay, rewards and incentives falls under which functional area of HRM?","options":["Workforce planning","Recruitment and selection","Training and development","Compensation management"],"correctOption":3,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Compensation management is the HRM area that designs pay, rewards and incentives. Option C builds skills and certifications, option B finds and hires talent, and option A sizes the workforce to fit strategy."}}$official_bank_source$::jsonb),
  ('official_bank_bua202', 'keep', 2, $official_bank_source${"itemId":"1192f48e-8790-5edb-a338-fd6ca7fa2771","revise":true,"payload":{"prompt":"The collective skills, knowledge and abilities of employees that contribute to an organisation's value are known as","options":["Working capital","Employee engagement","Talent management","Human capital"],"correctOption":3,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Human capital is the value held in employees' skills, knowledge and abilities. Option C is the strategy for attracting and developing such people, option B is their emotional commitment, and option A is a finance term for current assets minus current liabilities."}}$official_bank_source$::jsonb),
  ('official_bank_bua202', 'keep', 3, $official_bank_source${"itemId":"92fe35c3-217b-5c4e-b2d8-b3636a0f593a","revise":true,"payload":{"prompt":"The emotional commitment an employee has to the organisation and its goals is called","options":["Goal alignment","Job specification","Human capital","Employee engagement"],"correctOption":3,"section":"Nature, Scope and Importance of Human Resource Management","explanation":"Employee engagement is the emotional commitment staff feel towards the organisation and its goals. Option C is the skills and knowledge they hold, option B is a statement of a job's required qualifications, and option A is HR's work of linking individual output to corporate goals."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua202', 'keep', 4, $official_bank_source${"itemId":"1918dafc-1e62-5cd3-847e-8b89dfa856e0","revise":true,"payload":{"prompt":"The informal communication network through which information spreads within an organisation outside official channels is called:","options":["The grapevine","Downward communication","The organisation chart","A policy document"],"correctOption":0,"section":"Business Communication, Information Systems and Digital Management","explanation":"The grapevine is the unofficial network of conversations and social contacts through which information travels at work. Option B is a formal channel. Options C and D represent official structures and documents, which are formal by definition."}}$official_bank_source$::jsonb),
  ('official_bank_bua202', 'keep', 5, $official_bank_source${"itemId":"b89fab99-d49b-5314-b23f-35f435f7d37f","revise":true,"payload":{"prompt":"What is the correct order of the five stages of group development?","options":["Forming, Norming, Storming, Performing, Adjourning","Forming, Storming, Norming, Performing, Adjourning","Storming, Forming, Norming, Adjourning, Performing","Norming, Forming, Storming, Performing, Adjourning"],"correctOption":1,"section":"Organisational Behaviour, Communication and Team Dynamics","explanation":"Groups first come together (forming), then go through friction as opinions clash (storming), settle on norms and trust (norming), become productive (performing), and finally disband (adjourning). Options A, C and D each put at least one stage out of sequence; in particular, norming comes after storming, not before it."}}$official_bank_source$::jsonb),
