  ('official_bank_bua202', 'retire', 370, $official_bank_source$"eca96ada-5c59-50d0-b9d3-4fba713683f4"$official_bank_source$::jsonb),
  ('official_bank_bua202', 'retire', 371, $official_bank_source$"fb6fdee3-6f10-5923-92b1-ba7714ef2a19"$official_bank_source$::jsonb),
  ('official_bank_bua202', 'retire', 372, $official_bank_source$"5e04edaa-1435-5874-9e51-7f063d64a74f"$official_bank_source$::jsonb),
  ('official_bank_bua202', 'retire', 373, $official_bank_source$"063cca4c-ef5e-5738-aa88-c022e7787125"$official_bank_source$::jsonb),
  ('official_bank_bua202', 'retire', 374, $official_bank_source$"f227f3fb-fd32-55bb-aade-a19f02eae542"$official_bank_source$::jsonb),
  ('official_bank_bua202', 'retire', 375, $official_bank_source$"fd0c434b-e2ec-50de-a9ea-035ba0733d52"$official_bank_source$::jsonb),
